import{_ as t,o as n,c as a,l as i,t as r,N as o}from"./chunks/framework.Gjrf2Eoj.js";const u=JSON.parse('{"title":"ip-token | x-cmd man (ip man8) | tokenized interface identifier support","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-token - tokenized interface identifier support","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-token | x-cmd man (ip man8) | tokenized interface identifier support"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-token - tokenized interface identifier support"}]]},"headers":[],"params":{"isMan":true,"man":"ip-token","category":"ip man8","desc":"tokenized interface identifier support"},"relativePath":"ip/man8/ip-token.md","filePath":"ip/man8/ip-token.md"}'),s={name:"ip/man8/ip-token.md"},d={class:"visually-hidden"},l=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-token - tokenized interface identifier support</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip token</strong> { <em>COMMAND</em> | <strong>help</strong> }</p><p><strong>ip token set</strong> <em>TOKEN</em> <strong>dev</strong> <em>DEV</em></p><p><strong>ip token del dev</strong> <em>DEV</em></p><p><strong>ip token get</strong> [ <strong>dev</strong> <em>DEV</em> ]</p><p><strong>ip token</strong> [ <strong>list</strong> ]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>IPv6 tokenized interface identifier support is used for assigning well-known host-part addresses to nodes whilst still obtaining a global network prefix from Router advertisements. The primary target for tokenized identifiers are server platforms where addresses are usually manually configured, rather than using DHCPv6 or SLAAC. By using tokenized identifiers, hosts can still determine their network prefix by use of SLAAC, but more readily be automatically renumbered should their network prefix change [1]. Tokenized IPv6 Identifiers are described in the draft [1]: &lt;draft-chown-6man-tokenised-ipv6-identifiers-02&gt;.</p><h3 id="ip-token-set-set-an-interface-token" tabindex="-1">ip token set - set an interface token <a class="header-anchor" href="#ip-token-set-set-an-interface-token" aria-label="Permalink to &quot;ip token set - set an interface token&quot;">​</a></h3><p>set the interface token to the kernel.</p><dl><dt><em>TOKEN</em></dt><dd>the interface identifier token address.</dd><dt><strong>dev</strong> * DEV*</dt><dd>the networking interface.</dd></dl><h3 id="ip-token-del-delete-an-interface-token" tabindex="-1">ip token del - delete an interface token <a class="header-anchor" href="#ip-token-del-delete-an-interface-token" aria-label="Permalink to &quot;ip token del - delete an interface token&quot;">​</a></h3><p>delete the interface token from the kernel.</p><dl><dt><strong>dev</strong> * DEV*</dt><dd>the networking interface.</dd></dl><h3 id="ip-token-get-get-the-interface-token-from-the-kernel" tabindex="-1">ip token get - get the interface token from the kernel <a class="header-anchor" href="#ip-token-get-get-the-interface-token-from-the-kernel" aria-label="Permalink to &quot;ip token get - get the interface token from the kernel&quot;">​</a></h3><p>show a tokenized interface identifier of a particular networking device. <strong>Arguments:</strong> coincide with the arguments of <strong>ip token set</strong> but the <em>TOKEN</em> must be left out.</p><h3 id="ip-token-list-list-all-interface-tokens" tabindex="-1">ip token list - list all interface tokens <a class="header-anchor" href="#ip-token-list-list-all-interface-tokens" aria-label="Permalink to &quot;ip token list - list all interface tokens&quot;">​</a></h3><p>list all tokenized interface identifiers for the networking interfaces from the kernel.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Manpage by Daniel Borkmann</p>',24);function p(e,h,k,c,f,m){return n(),a("div",null,[i("h1",d,r(e.$params.man),1),l])}const b=t(s,[["render",p]]);export{u as __pageData,b as default};
